"""Landmark and factorization verifier for U(x) = x^3 - 3x."""
from __future__ import annotations


def U(x: float) -> float:
    return x ** 3 - 3.0 * x


def verify_landmarks() -> dict[str, float]:
    landmarks = {"near_human_peak": U(-1.0), "valley_bottom": U(1.0),
                 "recovery_point": U(2.0)}
    assert abs(landmarks["near_human_peak"] - 2.0) < 1e-12
    assert abs(landmarks["valley_bottom"] + 2.0) < 1e-12
    assert abs(landmarks["recovery_point"] - 2.0) < 1e-12
    return landmarks


def verify_factorizations(xs: list[float]) -> bool:
    for x in xs:
        assert abs((U(x) - 2.0) - (x - 2.0) * (x + 1.0) ** 2) < 1e-9
        assert abs((U(x) + 2.0) - (x - 1.0) ** 2 * (x + 2.0)) < 1e-9
    return True


if __name__ == "__main__":
    print(verify_landmarks())
    print("factorizations hold:", verify_factorizations([-2, -1, 0, 1, 2, 3]))

"""Regime-by-regime strict monotonicity checker for U(x) = x^3 - 3x."""
from __future__ import annotations


def U(x: float) -> float:
    return x ** 3 - 3.0 * x


def grid(lo: float, hi: float, n: int) -> list[float]:
    return [lo + (hi - lo) * i / (n - 1) for i in range(n)]


def is_strictly_increasing(xs: list[float]) -> bool:
    ys = [U(x) for x in xs]
    return all(ys[i] < ys[i + 1] for i in range(len(ys) - 1))


def is_strictly_decreasing(xs: list[float]) -> bool:
    ys = [U(x) for x in xs]
    return all(ys[i] > ys[i + 1] for i in range(len(ys) - 1))


def report() -> dict[str, bool]:
    return {
        "ascent_increasing": is_strictly_increasing(grid(-4.0, -1.0, 100)),
        "descent_decreasing": is_strictly_decreasing(grid(-1.0, 1.0, 100)),
        "recovery_increasing": is_strictly_increasing(grid(1.0, 4.0, 100)),
    }


if __name__ == "__main__":
    for k, v in report().items():
        print(f"{k}: {v}")

"""Uncanny-gap and full-recovery threshold explorer for U_c(x) = x^3 - 3 c^2 x."""
from __future__ import annotations


def U_c(x: float, c: float) -> float:
    return x ** 3 - 3.0 * c * c * x


def uncanny_gap(c: float) -> float:
    """Peak value U_c(-c) minus valley value U_c(c) = 4 c^3."""
    return U_c(-c, c) - U_c(c, c)


def full_recovery_holds(c: float, x: float) -> bool:
    """For x > 2c, acceptance exceeds the near-human peak U_c(-c)."""
    return U_c(x, c) > U_c(-c, c)


if __name__ == "__main__":
    for c in [0.5, 1.0, 2.0, 3.0]:
        print(f"c={c}: peak={U_c(-c, c):+.3f}, valley={U_c(c, c):+.3f}, "
              f"gap={uncanny_gap(c):+.3f} (=4c^3={4*c**3:.3f})")
    print("full recovery at x=2.001c for c=1:", full_recovery_holds(1.0, 2.001))

