from __future__ import annotations


def classify_regime(x: float) -> str:
    """Classify a human-likeness value into one of the three monotonic regimes
    of U(x) = x^3 - 3x. Critical points are at x = -1 and x = +1. O(1)."""
    if x < -1.0:
        return "ascent (strictly increasing)"
    if x < 1.0:
        return "uncanny descent (strictly decreasing)"
    return "recovery (strictly increasing)"


def local_direction(x: float) -> int:
    """Return +1 if U is increasing at x, -1 if decreasing, 0 at a critical point.
    Based on the derivative U'(x) = 3x^2 - 3 = 3(x-1)(x+1)."""
    d = 3.0 * x * x - 3.0
    if d > 0:
        return 1
    if d < 0:
        return -1
    return 0

from __future__ import annotations


def Q(a: float, b: float) -> float:
    """Symmetric quadratic factor: Q(a,b) = a^2 + ab + b^2 - 3."""
    return a * a + a * b + b * b - 3.0


def certified_monotonicity(a: float, b: float) -> str:
    """Given a < b within a single regime, decide the direction of U from the
    sign of the quadratic factor Q, mirroring the analytic proof. O(1).
    Uses U(b) - U(a) = (b - a) * Q(a, b)."""
    if not a < b:
        raise ValueError("require a < b")
    q = Q(a, b)
    if q > 0:
        return "U(a) < U(b): strictly increasing"
    if q < 0:
        return "U(b) < U(a): strictly decreasing"
    return "U(a) == U(b): flat (critical configuration)"

from __future__ import annotations


def U(x: float) -> float:
    return x ** 3 - 3.0 * x


def find_recovery_threshold(peak_value: float = 2.0, hi: float = 10.0,
                            tol: float = 1e-12) -> float:
    """Locate the least x > 1 with U(x) = peak_value by bisection on the strictly
    increasing recovery branch [1, inf). For the base model this returns x = 2.
    Complexity O(log((hi-1)/tol))."""
    lo = 1.0
    while hi - lo > tol:
        mid = 0.5 * (lo + hi)
        if U(mid) < peak_value:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)


if __name__ == "__main__":
    print("recovery threshold:", find_recovery_threshold())
